// Parse the AI response to extract tasks
const aiResponse = items[0].json.message.content;

try {
  // Extract JSON from the AI response (in case it's wrapped in markdown)
  const jsonMatch = aiResponse.match(/\[\s*{[\s\S]*}\s*\]/);
  const tasksJson = jsonMatch ? jsonMatch[0] : aiResponse;

  const tasks = JSON.parse(tasksJson);

  // Process each task and prepare for Notion
  const processedTasks = tasks.map((task, index) => {
    return {
      task_id: `TASK-${String(index + 1).padStart(3, '0')}`,
      title: task.title,
      description: task.description,
      priority: task.priority,
      effort: task.effort,
      category: task.category,
      dependencies: Array.isArray(task.dependencies) ? task.dependencies.join(', ') : '',
      acceptance_criteria: Array.isArray(task.acceptance_criteria) ? task.acceptance_criteria.join('\n• ') : '',
      status: 'Not Started',
      created_date: new Date().toISOString().split('T')[0]
    };
  });

  return processedTasks.map(task => ({ json: task }));

} catch (error) {
  throw new Error(`Failed to parse AI response: ${error.message}`);
}
